// Initialise an empty buffer
let analyseTexte = "Here is the list of products found on Amazon for analysis:\n\n";

// Walk through every product returned by Apify
for (const item of $input.all()) {
  const p = item.json;

  // Append the product info to the buffer
  analyseTexte += `📦 Product: ${p.productDescription}\n`;
  analyseTexte += `🔖 ASIN: ${p.asin}\n`;

  // Handle the current price and the strikethrough price
  analyseTexte += `💰 Current Price: ${p.price} €\n`;
  if (p.retailPrice && p.retailPrice > p.price) {
      analyseTexte += `📉 Original Price: ${p.retailPrice} €\n`;
  }

  analyseTexte += `⭐ Rating: ${p.productRating} (${p.countReview} reviews)\n`;
  analyseTexte += `📈 Recent Sales: ${p.salesVolume || "Not specified"}\n`;
  analyseTexte += `📢 Sponsored (Active Ads): ${p.sponsored ? "Yes" : "No"}\n`;
  analyseTexte += `🚀 Prime Shipping: ${p.prime ? "Yes" : "No"}\n`;
  analyseTexte += `🔗 Amazon Link: https://www.amazon.fr${p.dpUrl}\n`;
  analyseTexte += `🖼️ Image Link: ${p.imgUrl}\n`; // Used by the downstream Google Sheets node

  analyseTexte += `-----------------------------------\n`;
}

// Return the formatted buffer in a single field
return [{ json: { texte_pour_ia: analyseTexte } }];

// 1. Pick up the text generated by the AI (in the "output" field)
const reponseIA = $input.first().json.output;

// 2. Parse that text into a real array we can manipulate
const produits = JSON.parse(reponseIA);

// 3. Ask n8n to split the array into 5 separate items
// (this creates 5 executions of the next Google Sheets node — one row each)
return produits.map(produit => ({ json: produit }));

// 1. Collect the TikTok results returned by Apify
const resultatsTikTok = $input.all().map(item => item.json);

// 2. Get the Amazon product currently flowing through the loop (the "Loop" node)
const produit = $('Loop').first().json;

// Stat counters
let totalVues = 0;
let totalLikes = 0;
let totalShares = 0;
let totalSaves = 0; // "Saves" = strong purchase-intent signal
let totalComments = 0;
let videosRecentes = 0;
let nbVideos = 0;

// Trackers for the most viral video
let maxVues = 0;
let dateMaxVues = "Unknown";

// Keep a few descriptions to give the AI marketing context
let topDescriptions = [];

// Recency cut-off (60 days)
const dateLimite = new Date();
dateLimite.setDate(dateLimite.getDate() - 60);

// 3. Walk through each TikTok video found
for (const resultat of resultatsTikTok) {
    if (resultat.aweme_info && resultat.aweme_info.statistics) {
        nbVideos++;
        const stats = resultat.aweme_info.statistics;
        const video = resultat.aweme_info;

        // Pull the metrics
        let vues = stats.play_count || 0;
        let likes = stats.digg_count || 0;
        let shares = stats.share_count || 0;
        let saves = stats.collect_count || 0;
        let comments = stats.comment_count || 0;

        totalVues += vues;
        totalLikes += likes;
        totalShares += shares;
        totalSaves += saves;
        totalComments += comments;

        // Inspect the publish date
        let dateFormatee = "Unknown";
        if (video.create_time) {
            let dateVideo = new Date(video.create_time * 1000);
            dateFormatee = dateVideo.toLocaleDateString('fr-FR');

            // Posted within the last 60 days?
            if (dateVideo > dateLimite) {
                videosRecentes++;
            }
        }

        // Spot the video with the most views
        if (vues > maxVues) {
            maxVues = vues;
            dateMaxVues = dateFormatee;
        }

        // Keep snippets from the first 3 descriptions
        if (topDescriptions.length < 3 && video.desc) {
            topDescriptions.push(video.desc.substring(0, 100) + "...");
        }
    }
}

// 4. Engagement rates (kept as proper Number values)
let tauxLikes = totalVues > 0 ? parseFloat(((totalLikes / totalVues) * 100).toFixed(2)) : 0;
let tauxSaves = totalVues > 0 ? parseFloat(((totalSaves / totalVues) * 100).toFixed(2)) : 0; 
let tauxShares = totalVues > 0 ? parseFloat(((totalShares / totalVues) * 100).toFixed(2)) : 0; 

// 5. Build the final "Product Dossier" handed off to the AI Agent
return [{
    json: {
        // Re-include all the Amazon and Shopify data from the start
        ...produit, 

        // Add the pre-digested TikTok analysis block
        "TikTok_Data": {
            "Videos_Analysees": nbVideos,
            "Videos_Postees_Moins_60j": videosRecentes,

            "Metriques_Globales": {
                "Total_Vues": totalVues,
                "Total_Likes": totalLikes,
                "Total_Favoris": totalSaves,
                "Total_Partages": totalShares,
                "Total_Commentaires": totalComments
            },

            "Taux_Engagement": {
                // Variables are already plain numbers at this point
                "Taux_Likes_Sur_Vues_pct": tauxLikes,
                "Taux_Intentions_Achat_Favoris_pct": tauxSaves,
                "Taux_Viralite_Partages_pct": tauxShares
            },

            "Video_La_Plus_Virale": {
                "Vues": maxVues,
                "Date_Publication": dateMaxVues
            },

            "Angles_Marketing_Concurrents": topDescriptions
        }
    }
}];

